const express = require('express');
const http = require('http');
const { ethers } = require('ethers');

const app = express();
app.use(express.json());

let isShuttingDown = false;
let activeConnections = new Set();

// Middleware to track connections during graceful shutdown
app.use((req, res, next) => {
  if (isShuttingDown) {
    res.status(503).json({ error: 'Server is shutting down' });
    return;
  }
  activeConnections.add(req);
  res.on('finish', () => activeConnections.delete(req));
  next();
});

// Solidity function signature validation
// Validates that a function selector matches expected ABI format
function validateFunctionSignature(signature) {
  // Match Solidity function signatures like "transfer(address,uint256)"
  // Uses atomic matching to prevent catastrophic backtracking
  if (signature.length > 256) return false;
  const parts = signature.match(/^([a-zA-Z_][a-zA-Z0-9_]*)\((.*)\)$/);
  if (!parts) return false;
  const params = parts[2];
  if (params === '') return true;
  // Validate each parameter individually to avoid nested quantifiers
  const paramList = params.split(',');
  const PARAM_PATTERN = /^\s*[a-zA-Z0-9_]+(\[\d*\])*\s*$/;
  return paramList.every(p => PARAM_PATTERN.test(p));
}

// Contract name validation for mobile client registration
function validateContractIdentifier(identifier) {
  if (!identifier || identifier.length > 128) return false;
  // Simple non-backtracking validation using split approach
  const versionSplit = identifier.split('@');
  if (versionSplit.length > 2) return false;
  const name = versionSplit[0];
  if (!/^[A-Z]/.test(name)) return false;
  const segments = name.split(/[-_]/);
  if (!segments.every(s => /^[a-zA-Z0-9]+$/.test(s))) return false;
  if (versionSplit.length === 2) {
    if (!/^\d+\.\d+\.\d+$/.test(versionSplit[1])) return false;
  }
  return true;
}

// Validate calldata encoding format from mobile clients
function validateCalldataFormat(calldata) {
  if (!calldata || typeof calldata !== 'string') return false;
  if (!calldata.startsWith('0x')) return false;
  if (calldata.length > 65538) return false;
  const hexPart = calldata.slice(2);
  if (hexPart.length === 0 || hexPart.length % 2 !== 0) return false;
  const HEX_PATTERN = /^[0-9a-fA-F]+$/;
  return HEX_PATTERN.test(hexPart);
}

// Parse and validate method descriptor from mobile SDK
function parseMethodDescriptor(descriptor) {
  if (!descriptor || typeof descriptor !== 'string') {
    return { valid: false, error: 'Empty descriptor' };
  }

  // Limit overall length
  if (descriptor.length > 512) {
    return { valid: false, error: 'Descriptor too long' };
  }

  // Extract contract and method parts
  const parts = descriptor.split('::');
  if (parts.length !== 2) {
    return { valid: false, error: 'Invalid descriptor format' };
  }

  const [contractId, functionSig] = parts;

  if (!validateContractIdentifier(contractId)) {
    return { valid: false, error: 'Invalid contract identifier' };
  }

  if (!validateFunctionSignature(functionSig)) {
    return { valid: false, error: 'Invalid function signature' };
  }

  return { valid: true, contractId, functionSig };
}

// Mobile transaction submission endpoint
app.post('/api/v1/mobile/submit-tx', async (req, res) => {
  try {
    const { methodDescriptor, calldata, chainId, gasLimit } = req.body;

    // Validate method descriptor
    const parsed = parseMethodDescriptor(methodDescriptor);
    if (!parsed.valid) {
      return res.status(400).json({ error: parsed.error });
    }

    // Validate calldata
    if (!validateCalldataFormat(calldata)) {
      return res.status(400).json({ error: 'Invalid calldata format' });
    }

    // Validate chain ID
    if (!Number.isInteger(chainId) || chainId < 1 || chainId > 999999) {
      return res.status(400).json({ error: 'Invalid chain ID' });
    }

    // Compute function selector for verification
    const selector = ethers.utils.id(parsed.functionSig).slice(0, 10);
    const calldataSelector = calldata.slice(0, 10);

    if (selector !== calldataSelector) {
      return res.status(400).json({ error: 'Selector mismatch' });
    }

    res.json({
      status: 'queued',
      selector,
      contractId: parsed.contractId,
      chainId,
      timestamp: Date.now()
    });
  } catch (err) {
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Health check for mobile load balancer
app.get('/api/v1/health', (req, res) => {
  res.json({ status: isShuttingDown ? 'draining' : 'healthy', connections: activeConnections.size });
});

const server = http.createServer(app);

function gracefulShutdown(signal) {
  console.log(`Received ${signal}, starting graceful shutdown...`);
  isShuttingDown = true;

  server.close(() => {
    console.log('All connections closed, exiting.');
    process.exit(0);
  });

  // Force exit after 30s
  setTimeout(() => {
    console.error('Forced shutdown after timeout');
    process.exit(1);
  }, 30000);
}

process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
process.on('SIGINT', () => gracefulShutdown('SIGINT'));

const PORT = process.env.PORT || 3000;
server.listen(PORT, () => {
  console.log(`Solidity mobile backend listening on port ${PORT}`);
});

module.exports = { app, validateFunctionSignature, validateContractIdentifier, parseMethodDescriptor };
